//! UTD wedge diffraction against the exact BTM solution (fixtures generated by `tools/diffraction/`), the
//! RS5 half-plane geometries in the signed-band-gain representation of the core, and the shadow boundary.

use crate::ism::utd::band_rms;
use crate::ism::{self, Bands, IsmCache, Material, Path, Scene, Wall, AIR_DB_PER_M, NB, SPEED_OF_SOUND};
use std::f64::consts::PI;

// ---- a tiny JSON reader (the crate has no dependencies)

#[derive(Debug, Clone)]
enum J {
    Num(f64),
    Bool(bool),
    #[allow(dead_code)]
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

impl J {
    fn get(&self, k: &str) -> &J {
        match self {
            J::Obj(m) => &m.iter().find(|(n, _)| n == k).unwrap_or_else(|| panic!("no key {k}")).1,
            _ => panic!("not an object"),
        }
    }
    fn f(&self) -> f64 {
        match self {
            J::Num(v) => *v,
            _ => panic!("not a number: {self:?}"),
        }
    }
    fn b(&self) -> bool {
        matches!(self, J::Bool(true))
    }
    fn arr(&self) -> &[J] {
        match self {
            J::Arr(v) => v,
            _ => panic!("not an array"),
        }
    }
}

struct Reader<'a> {
    s: &'a [u8],
    i: usize,
}

impl Reader<'_> {
    fn ws(&mut self) {
        while self.i < self.s.len() && self.s[self.i].is_ascii_whitespace() {
            self.i += 1;
        }
    }
    fn eat(&mut self, c: u8) {
        self.ws();
        assert_eq!(self.s[self.i], c, "expected {} at {}", c as char, self.i);
        self.i += 1;
    }
    fn string(&mut self) -> String {
        self.eat(b'"');
        let a = self.i;
        while self.s[self.i] != b'"' {
            self.i += 1; // the fixtures hold no escapes
        }
        self.i += 1;
        String::from_utf8(self.s[a..self.i - 1].to_vec()).unwrap()
    }
    fn value(&mut self) -> J {
        self.ws();
        match self.s[self.i] {
            b'{' => {
                self.i += 1;
                let mut m = Vec::new();
                loop {
                    self.ws();
                    if self.s[self.i] == b'}' {
                        self.i += 1;
                        return J::Obj(m);
                    }
                    if !m.is_empty() {
                        self.eat(b',');
                    }
                    let k = self.string();
                    self.eat(b':');
                    m.push((k, self.value()));
                }
            }
            b'[' => {
                self.i += 1;
                let mut v = Vec::new();
                loop {
                    self.ws();
                    if self.s[self.i] == b']' {
                        self.i += 1;
                        return J::Arr(v);
                    }
                    if !v.is_empty() {
                        self.eat(b',');
                    }
                    v.push(self.value());
                }
            }
            b'"' => J::Str(self.string()),
            b't' => {
                self.i += 4;
                J::Bool(true)
            }
            b'f' => {
                self.i += 5;
                J::Bool(false)
            }
            _ => {
                let a = self.i;
                while self.i < self.s.len() && matches!(self.s[self.i], b'-' | b'+' | b'.' | b'e' | b'E' | b'0'..=b'9') {
                    self.i += 1;
                }
                J::Num(std::str::from_utf8(&self.s[a..self.i]).unwrap().parse().unwrap())
            }
        }
    }
}

fn parse(s: &str) -> J {
    Reader { s: s.as_bytes(), i: 0 }.value()
}

const WEDGE_BTM: &str = include_str!("../testdata/wedge_btm.json");
const RS5_BTM: &str = include_str!("../testdata/rs5_halfplane_btm.json");

// ---- 1. port of utd_A against the BTM wedge fixture

#[test]
fn utd_matches_the_btm_wedge_fixture() {
    let root = parse(WEDGE_BTM);
    let cases = root.get("cases").arr();
    assert_eq!(cases.len(), 24);
    let (mut worst, mut worst_case) = (0.0f64, 0);
    let (mut worst_lit, mut worst_shadow) = (0.0f64, 0.0f64);
    for (ci, c) in cases.iter().enumerate() {
        let (n, ps, pl) = (c.get("n").f(), c.get("phi_s").f(), c.get("phi_l").f());
        let (rs, rr, dz) = (c.get("rs").f(), c.get("rr").f(), c.get("dz").f());
        // Edge along z, source at z = 0, listener at z = dz, both rs / rr (horizontally) from the edge.
        let zc = dz * rs / (rs + rr);
        let r1 = rs.hypot(zc);
        let r2 = rr.hypot(dz - zc);
        let sinb = rs / r1;
        let btm = c.get("btm_db").arr();
        for b in 0..NB {
            let utd = 20.0 * band_rms(b, ps, pl, n, r1, r2, sinb).log10();
            let d = (utd - btm[b].f()).abs();
            if d > worst {
                (worst, worst_case) = (d, ci);
            }
            if c.get("lit").b() {
                worst_lit = worst_lit.max(d);
            } else {
                worst_shadow = worst_shadow.max(d);
            }
        }
    }
    eprintln!("UTD vs BTM wedge: max |diff| {worst:.3} dB (case {worst_case}), lit {worst_lit:.3}, shadow {worst_shadow:.3}");
    assert!(worst <= 0.35, "max |diff| {worst:.3} dB in case {worst_case}");
}

#[test]
fn utd_boundary_limit_is_continuous() {
    // A term exactly on a shadow boundary uses the analytic limit; just beside it the value must agree.
    let (n, r1, r2, sinb) = (2.0, 2.0, 3.0, 1.0);
    let ps = 1.0;
    for (pl, label) in [(ps + PI, "shadow boundary"), (PI - ps, "reflection boundary")] {
        for b in 0..NB {
            let on = band_rms(b, ps, pl, n, r1, r2, sinb);
            let near_p = band_rms(b, ps, pl + 1e-7, n, r1, r2, sinb);
            let near_m = band_rms(b, ps, pl - 1e-7, n, r1, r2, sinb);
            let tol = 1e-4 * on.max(near_p).max(near_m);
            assert!((on - near_p).abs() < tol || (on - near_m).abs() < tol, "{label} band {b}: {on} vs {near_m} / {near_p}");
        }
    }
    // On the shadow boundary of a half-plane |A| -> 1/2 at every frequency far from the edge (kL large).
    let a = crate::ism::utd::a_sq(1.0, 1.0 + PI, 2.0, 50.0, 50.0, 1.0, 2.0 * PI * 4000.0 / SPEED_OF_SOUND).sqrt();
    assert!((a - 0.5).abs() < 0.02, "{a}");
}

// ---- scenes

fn opaque() -> Material {
    Material::new(Bands::splat(0.1), 0.0)
}

fn mat(alpha: f64) -> Material {
    Material::new(Bands::splat(alpha), 0.0)
}

fn paths_of(sc: &Scene, src: [f64; 3], lis: [f64; 3], order: u32) -> Vec<Path> {
    let mut cache = IsmCache::default();
    let (nodes, edges) = cache.tree_and_edges(sc, 1, [src[0], src[1]], order, true);
    ism::compute_paths_with_edges(sc, nodes, edges, src, lis, order)
}

fn air(b: usize, r: f64) -> f64 {
    10f64.powf(-AIR_DB_PER_M[b] * r / 20.0)
}

const FC: [f64; NB] = [125.0, 250.0, 500.0, 1000.0, 2000.0, 4000.0];

// ---- 2. RS5 half-plane geometries (BRAS x / z -> plan x / height, y irrelevant)

#[test]
fn rs5_half_plane_band_levels_match_btm() {
    let root = parse(RS5_BTM);
    // Thin rigid partition (opaque, up to the top edge at 2.066 m) along y; ceiling high and floor / ceiling fully
    // absorbing (no folded paths, no ISM floor paths), no other walls.
    let wall = Wall::partial([5.487, -50.0], [5.487, 50.0], 0, 0.0, 2.066);
    let sc = Scene::new(vec![wall], vec![opaque(), mat(1.0)], 10.0, 1, 1);
    let (mut worst_sh, mut worst_vis) = (0.0f64, 0.0f64);
    let (mut sum_sh, mut n_sh, mut sum_vis, mut n_vis) = (0.0, 0, 0.0, 0);
    for row in root.get("rows").arr() {
        let (s, l) = (row.get("src").arr(), row.get("lis").arr());
        let src = [s[0].f(), 0.0, s[1].f()];
        let lis = [l[0].f(), 0.0, l[1].f()];
        let visible = row.get("visible").b();
        let path_len = row.get("path_len").f();
        let paths = paths_of(&sc, src, lis, 0);
        let want = row.get("total_db_re_free_field").arr();
        for b in 0..NB {
            // mean over 24 log-spaced freqs of |sum g_b exp(-jk r)|^2 (air absorption divided out)
            let mut acc = 0.0;
            for i in 0..24 {
                let f = FC[b] * 2f64.powf(-0.5 + i as f64 / 23.0);
                let k = 2.0 * PI * f / SPEED_OF_SOUND;
                let (mut re, mut im) = (0.0, 0.0);
                for p in &paths {
                    let g = p.gains[b] / air(b, p.r);
                    re += g * (k * p.r).cos();
                    im -= g * (k * p.r).sin();
                }
                acc += re * re + im * im;
            }
            let db = 10.0 * (acc / 24.0).log10() + 20.0 * path_len.log10();
            let err = db - want[b].f();
            if visible {
                worst_vis = worst_vis.max(err.abs());
                sum_vis += err.abs();
                n_vis += 1;
            } else {
                worst_sh = worst_sh.max(err.abs());
                sum_sh += err.abs();
                n_sh += 1;
            }
        }
    }
    eprintln!(
        "RS5 vs BTM: shadow max {worst_sh:.3} mean|err| {:.3} (n={n_sh}); visible max {worst_vis:.3} mean|err| {:.3} (n={n_vis})",
        sum_sh / n_sh as f64,
        sum_vis / n_vis as f64
    );
    assert!(worst_sh <= 0.4, "shadow max {worst_sh:.3} dB");
    assert!(worst_vis <= 0.9, "visible max {worst_vis:.3} dB");
}

// ---- 3. shadow boundary of the doorway jamb

/// Room `w` x `h` (3 m high), partition at x = w / 2 from y = 0 to the jamb at y = `jamb`.
fn doorway(w: f64, h: f64, jamb: f64) -> Scene {
    let c = [[0.0, 0.0], [w, 0.0], [w, h], [0.0, h]];
    let mut walls: Vec<Wall> = (0..4).map(|i| Wall::full(c[i], c[(i + 1) % 4], 0)).collect();
    walls.push(Wall::full([w / 2.0, 0.0], [w / 2.0, jamb], 0));
    Scene::new(walls, vec![opaque()], 3.0, 0, 0)
}

/// Level re the free field (dB) of the order-0 paths of band `b` for the listener at (`x`, `y`), amplitudes added
/// with their signs (the geometric and the diffracted delays coincide to within micrometres near the boundary).
fn boundary_level(sc: &Scene, src: [f64; 3], x: f64, y: f64, b: usize) -> (f64, bool) {
    let lis = [x, y, 1.2];
    let p = paths_of(sc, src, lis, 0);
    let r = ((src[0] - lis[0]).powi(2) + (src[1] - lis[1]).powi(2) + (src[2] - lis[2]).powi(2)).sqrt();
    let sum: f64 = p.iter().filter(|x| x.order == 0).map(|x| x.gains[b] / air(b, x.r)).sum();
    let lit = p.iter().any(|x| x.order == 0 && x.pts.len() == 2);
    (20.0 * (sum.abs() * r).log10(), lit)
}

/// Levels just below (shadow) and above (lit) the boundary line through the jamb, per band: (shadow, lit).
fn across_boundary(sc: &Scene, src: [f64; 3], x: f64, y_boundary: f64, d: f64) -> Vec<(f64, f64)> {
    (0..NB)
        .map(|b| {
            let (below, lit_b) = boundary_level(sc, src, x, y_boundary - d, b);
            let (above, lit_a) = boundary_level(sc, src, x, y_boundary + d, b);
            assert!(!lit_b && lit_a, "shadow below, lit above");
            (below, above)
        })
        .collect()
}

#[test]
fn shadow_boundary_is_continuous() {
    // Small doorway (legs ~1.1 m, k L ~ 1.3 at 125 Hz). The line through the jamb (5, 4) hits x = 6 at y = 4.5.
    let sc = doorway(10.0, 5.0, 4.0);
    let mut worst = 0.0f64;
    for d in [0.002, 0.004, 0.008] {
        for (sh, lit) in across_boundary(&sc, [4.0, 3.5, 1.2], 6.0, 4.5, d) {
            worst = worst.max((lit - sh).abs());
        }
    }
    // Listener exactly on the boundary line (the geometric classification and the UTD side must agree there).
    for b in 0..NB {
        let (on, _) = boundary_level(&sc, [4.0, 3.5, 1.2], 6.0, 4.5, b);
        let (near, _) = boundary_level(&sc, [4.0, 3.5, 1.2], 6.0, 4.5 - 0.002, b);
        worst = worst.max((on - near).abs());
    }
    eprintln!("small doorway: max step {worst:.3} dB");
    assert!(worst <= 0.5, "step {worst:.2} dB");
}

#[test]
fn shadow_boundary_is_6_db_down() {
    // Large room (legs ~20 m, k L ~ 23 at 125 Hz, so the terms beside the singular one are small): |A| -> 1/2, -6 dB,
    // geometric - 1/2 (lit) and + 1/2 (shadow). (With 10 m legs the 125 Hz band is still 0.75 dB off: that is the
    // physical size of the smooth diffraction terms at k L ~ 12, not a defect.)
    // S = (20, 24), jamb (40, 20): the line hits x = 60 at y = 16 (shadow below, lit above).
    let sc = doorway(80.0, 40.0, 20.0);
    let (mut worst_dev, mut worst_step) = (0.0f64, 0.0f64);
    for d in [0.002, 0.004, 0.008] {
        for (sh, lit) in across_boundary(&sc, [20.0, 24.0, 1.2], 60.0, 16.0, d) {
            worst_dev = worst_dev.max((sh + 6.02).abs()).max((lit + 6.02).abs());
            worst_step = worst_step.max((lit - sh).abs());
        }
    }
    eprintln!("large room: max |level + 6.02| {worst_dev:.3} dB, max step {worst_step:.3} dB");
    assert!(worst_dev <= 0.7, "level {worst_dev:.2} dB from -6");
    assert!(worst_step <= 0.5, "step {worst_step:.2} dB");
}

// ---- coherent ETC

fn etc_band_sum(paths: &[Path], b: usize) -> f64 {
    let hist = crate::rays::Hist::empty(600);
    let etc = crate::metrics::build_etc(paths, &hist);
    etc.e[b * etc.nbins..(b + 1) * etc.nbins].iter().sum()
}

#[test]
fn etc_of_a_lit_pair_at_the_shadow_boundary_is_coherent() {
    // Large room, listener 2 mm on the lit side of the boundary: geometric 1 and diffracted -1/2 add to ~1/4 of the
    // free-field direct energy (incoherently it would be 1.25).
    let sc = doorway(80.0, 40.0, 20.0);
    let src = [20.0, 24.0, 1.2];
    let lis = [60.0, 16.002, 1.2];
    let p = paths_of(&sc, src, lis, 0);
    assert!(p.iter().any(|x| x.order == 0 && x.pts.len() == 2) && p.iter().any(|x| x.order == 0 && x.pts.len() == 3));
    let r = ((src[0] - lis[0]).powi(2) + (src[1] - lis[1]).powi(2) + (src[2] - lis[2]).powi(2)).sqrt();
    for b in 0..NB {
        let free = (air(b, r) / r).powi(2);
        let rel = etc_band_sum(&p, b) / free;
        assert!(rel > 0.2 && rel < 0.35, "band {b}: {rel:.3} of the free-field direct energy");
    }
}

#[test]
fn etc_sums_ungrouped_paths_as_energies_and_groups_coherently() {
    let path = |r: f64, g: f64, coh: u32| Path { order: 0, r, gains: Bands::splat(g), dir: [1.0, 0.0, 0.0], pts: vec![], crossed: 0, coh };
    // Ungrouped paths add as energies, also at exactly equal length (idealised symmetric rooms) and 30 ms apart.
    let plain = [path(10.0, 0.3, 0), path(10.0, 0.2, 0)];
    let far = [path(10.0, 0.3, 0), path(10.0 + 0.03 * SPEED_OF_SOUND, 0.2, 0)];
    for b in 0..NB {
        assert_eq!(etc_band_sum(&plain, b), 0.3f64 * 0.3 + 0.2 * 0.2);
        assert_eq!(etc_band_sum(&far, b), 0.3f64 * 0.3 + 0.2 * 0.2);
    }
    // One group of equal delay: (g1 + g2)^2; opposite signs: (g1 - g2)^2.
    let same = [path(10.0, 0.3, 1), path(10.0, 0.2, 1)];
    let opp = [path(10.0, 0.3, 1), path(10.0, -0.2, 1)];
    // Two groups of the same delay do not interfere with each other.
    let two = [path(10.0, 0.3, 1), path(10.0, 0.2, 1), path(10.0, 0.5, 2), path(10.0, -0.1, 2)];
    for b in 0..NB {
        assert!((etc_band_sum(&same, b) - 0.25).abs() < 1e-12);
        assert!((etc_band_sum(&opp, b) - 0.01).abs() < 1e-12);
        assert!((etc_band_sum(&two, b) - (0.25 + 0.16)).abs() < 1e-12);
    }
}

#[test]
fn etc_group_shares_are_non_negative_and_sum_to_the_group_energy() {
    // Three members with different delays (a lit pair plus a third path): E = mean_f |sum g e^{-jk r}|^2 per band.
    let path = |r: f64, g: f64| Path { order: 0, r, gains: Bands::from_fn(|b| g * (1.0 + 0.1 * b as f64)), dir: [1.0, 0.0, 0.0], pts: vec![], crossed: 0, coh: 7 };
    let members = [path(10.0, 0.4), path(10.03, -0.3), path(10.9, 0.1)];
    for b in 0..NB {
        let idx = [0, 1, 2];
        let shares = crate::metrics::group_shares(&members, &idx, b);
        assert!(shares.iter().all(|&s| s >= 0.0));
        let mut e = 0.0;
        for i in 0..8 {
            let k = 2.0 * PI * FC[b] * 2f64.powf(-0.5 + i as f64 / 7.0) / SPEED_OF_SOUND;
            let (mut re, mut im) = (0.0, 0.0);
            for m in &members {
                re += m.gains[b] * (k * m.r).cos();
                im -= m.gains[b] * (k * m.r).sin();
            }
            e += re * re + im * im;
        }
        assert!((shares.iter().sum::<f64>() - e / 8.0).abs() < 1e-12);
        // All gains zero in the band: nothing.
        let zero: Vec<Path> = members.iter().map(|m| Path { gains: Bands::splat(0.0), ..m.clone() }).collect();
        assert!(crate::metrics::group_shares(&zero, &idx, b).iter().all(|&s| s == 0.0));
    }
}

#[test]
fn etc_bins_stay_non_negative_in_the_test_scenes() {
    // Doorway / low wall / partitions with floor and ceiling combinations, many listener positions (shadow, lit, boundary).
    let c = [[0.0, 0.0], [10.0, 0.0], [10.0, 5.0], [0.0, 5.0]];
    let room = |extra: Vec<Wall>, floor: f64| {
        let mut walls: Vec<Wall> = (0..4).map(|i| Wall::full(c[i], c[(i + 1) % 4], 0)).collect();
        walls.extend(extra);
        Scene::new(walls, vec![opaque(), mat(floor), mat(0.05)], 3.0, 1, 2)
    };
    let scenes = [
        room(vec![Wall::full([5.0, 0.0], [5.0, 4.0], 0)], 0.05),
        room(vec![Wall::partial([5.0, 0.0], [5.0, 5.0], 0, 0.0, 0.5)], 0.05),
        room(vec![Wall::partial([5.0, 0.0], [5.0, 5.0], 0, 0.0, 2.0)], 0.01),
        room(vec![Wall::partial([3.0, 0.0], [3.0, 5.0], 0, 0.0, 1.5), Wall::partial([6.0, 0.0], [6.0, 3.0], 0, 0.5, 2.0)], 0.2),
    ];
    let (mut configs, mut grouped, mut neg) = (0, 0, 0);
    for sc in &scenes {
        for si in 0..4 {
            let src = [1.0 + si as f64 * 0.7, 1.0 + si as f64 * 0.9, 0.3 + 0.4 * si as f64];
            for ix in 0..24 {
                for iy in 0..10 {
                    let lis = [5.2 + ix as f64 * 0.19, 0.3 + iy as f64 * 0.47, 0.05 + 0.3 * ((ix + iy) % 8) as f64];
                    let p = paths_of(sc, src, lis, 2);
                    let etc = crate::metrics::build_etc(&p, &crate::rays::Hist::empty(300));
                    neg += etc.e.iter().filter(|&&v| v < 0.0).count();
                    configs += 1;
                    grouped += p.iter().any(|x| x.coh != 0) as usize;
                }
            }
        }
    }
    eprintln!("ETC: {configs} configurations ({grouped} with coherence groups), negative bins: {neg}");
    assert!(grouped > 100);
    assert_eq!(neg, 0);
}

#[test]
fn coherence_groups_follow_the_geometry() {
    let sc = doorway(80.0, 40.0, 20.0);
    let src = [20.0, 24.0, 1.2];
    // Lit: the geometric path and its negative diffracted path are one group.
    let lit = paths_of(&sc, src, [60.0, 16.5, 1.2], 0);
    let g: Vec<&Path> = lit.iter().filter(|p| p.coh != 0).collect();
    assert!(g.len() == 2 && g[0].coh == g[1].coh);
    assert!(g.iter().any(|p| p.pts.len() == 2 && p.gains[0] > 0.0) && g.iter().any(|p| p.pts.len() == 3 && p.gains[0] < 0.0));
    // Shadow: the diffracted paths of different edges are different groups; no geometric path.
    let sh = paths_of(&sc, src, [60.0, 15.5, 1.2], 0);
    assert!(sh.iter().all(|p| p.pts.len() != 2 || p.coh == 0));
    let ids: Vec<u32> = sh.iter().filter(|p| p.pts.len() == 3).map(|p| p.coh).collect();
    assert!(!ids.is_empty() && ids.iter().all(|&i| i != 0));
}
